message.content:
{
  "gate_token": "YdDgNJSSx4PR99YGNTZEmA",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A map is unrolled at the edge of the ruined royal city.",
      "visual_description": "Mara spreads a stained map on a broken parapet, the skyline of shattered spires behind her at dusk.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The lamp warns of a path that lies.",
      "visual_description": "An oil lamp held aloft, its single flame-eye narrowing as it stares down a fog-choked avenue lined with old royal banners.guards",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "A clockwork scout slips ahead through rubble.",
      "visual_description": "A small tin fox with blue glass eyes darts between toppled statues, key-wind tail ticking softly in the gloom.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The diver arrives through a cracked shop window.",
      "visual_description": "A figure in a clear diving helmet steps out of a fractured pane of glass, coat shimmering with reflected lantern light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers at the castle gates.",
      "visual_description": "Massive iron gates lean half off their hinges; four figures cluster in their shadow, planning quietly under torn pennants.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "A dozing official blocks the toll booth.",
      "visual_description": "A round man slumps over a ledger pillow in a crooked booth, stamped papers fluttering from his sleeves as the wind picks up.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "Mara forges a passage stamp from the sleeper's hand.",
      "visual_description": "Mara gently lifts the snoring official's wrist to press his stamp onto her own forged writ, brass compass swinging at her belt.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "The cursed tower hums above them.",
      "visual_description": "A leaning black tower wreathed in violet sparks; the tin fox stares up, ears twitching, gears whirring faster.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Armored patrols march the cobbled square.",
      "visual_description": "Rows of helmeted figures clank past in lockstep, seen from above as Mara and the diver crouch on a slate rooftop.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Frightened townsfolk whisper of a winged beast.",
      "visual_description": "Hooded figures huddle around the oracle lamp in an alley shrine, pointing at clawed gouges torn across a cathedral roof.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The rumored beast is only a painted banner.",
      "visual_description": "A huge tattered royal banner of a serpent flaps in the wind against a red moon; the tin fox sniffs the cloth, unimpressed.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door demands a true name.",
      "visual_description": "A silver door set into a courtyard wall, its surface rippling like water; the lamp's flame-eye widens as runes light up.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The diver swims through the door's mirrored surface.",
      "visual_description": "The diver plunges headfirst into the silver door as if into a pool, coat billowing, helmet bubbles trailing behind.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Inside the throne hall, the prisoner waits.",
      "visual_description": "The diver surfaces from a polished shield on the wall into a dusty hall where the tin fox already sits beside a chained ledger trunk.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The prisoner is the snoring official himself.",
      "visual_description": "The diver lifts the chained sleeper from the trunk; the man's ledger pillow falls open to reveal stolen city deeds glowing faintly.",
      "characters": ["glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Mara signals retreat from the cracked bell tower.",
      "visual_description": "Mara waves a green lantern from a leaning belfry, her ink-stained coat snapping in wind as patrol horns echo below.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "The lamp lights the way to the bridge.",
      "visual_description": "A narrow stone bridge stretches over a black river; the oracle lamp floats ahead, its single eye casting a long pale beam.",
      "characters": ["oracle_lamp", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 18,
      "caption": "They cross the bridge as the city collapses behind them.",
      "visual_description": "All five figures hurry across the bridge at dawn; towers crumble in the distance and the official, finally awake, clutches his ledger in astonishment.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

